package com.frostsecurity.extreme.audit; import java.util.*; public final class AuthorizedScope { private final Set<String> targets=new HashSet<>(); public void allow(String target){if(target!=null&&!target.isBlank())targets.add(target.toLowerCase());} public boolean allows(String target){return target!=null&&targets.contains(target.toLowerCase());} public Set<String> targets(){return Set.copyOf(targets);} }